import type { AudioManifest, ManifestTrack } from "./manifestTypes.js";

/**
 * Sound packs. Three sets of files with the same track ids:
 *
 * - `synth`: everything generated by this package's own code (`assets/audio`, the
 *   project's licence; the end of every fallback chain);
 * - `studio`: recordings generated with ElevenLabs from text prompts and post-processed by this
 *   package (`assets/audio-studio`; see its LICENSES.md: its redistribution terms are not settled);
 * - `remaster` ("Original, remastered"): new recordings generated with ElevenLabs from text prompts
 *   written to resemble the 2001 game's own sounds, one per original sound, at modern fidelity
 *   (`assets/audio-remaster`). They are not the 2001 recordings, and no 2001 audio was used to
 *   make them. Only the tracks that had a 2001 counterpart exist; the rest play from Studio, then Synth.
 *
 * A player picks a pack, or leaves the setting on "auto" (the default), which picks by what is
 * being played (`AUTO_PACK`: the Classic game plays the remaster, the Expanded game Studio). Any
 * id the chosen pack lacks plays from the next pack in `FALLBACK_ORDER`, so a partial pack never
 * leaves the game silent.
 */
export const PACK_IDS = ["synth", "studio", "remaster"] as const;
export type PackId = (typeof PACK_IDS)[number];

export interface AudioPackInfo {
  id: PackId;
  /** Directory under the repository's assets/ (and under the client's asset root). */
  dir: string;
  title: string;
  /** One line for players, in the settings. */
  description: string;
}

export const PACKS: Record<PackId, AudioPackInfo> = {
  synth: {
    id: "synth",
    dir: "audio",
    title: "Synth",
    description: "Made by the game's own code.",
  },
  studio: {
    id: "studio",
    dir: "audio-studio",
    title: "Studio",
    description:
      "New music and effects generated with ElevenLabs; anything missing plays from Synth.",
  },
  remaster: {
    id: "remaster",
    dir: "audio-remaster",
    title: "Original, remastered",
    description:
      "New audio made to resemble the 2001 game's sounds, not the 2001 recordings; anything without a 2001 counterpart plays from Studio, then Synth.",
  },
};

export const isPackId = (x: unknown): x is PackId =>
  typeof x === "string" && (PACK_IDS as readonly string[]).includes(x);

/** What the player's Sound pack setting can be: one of the packs, or "auto" (by ruleset). */
export const PACK_SETTINGS = ["auto", ...PACK_IDS] as const;
export type PackSetting = (typeof PACK_SETTINGS)[number];

/** Owner's decision 15a (2026-11-06): Automatic is the default; an explicit choice overrides it. */
export const DEFAULT_PACK_SETTING: PackSetting = "auto";

export const isPackSetting = (x: unknown): x is PackSetting =>
  typeof x === "string" && (PACK_SETTINGS as readonly string[]).includes(x);

/**
 * THE FALLBACK TABLE: when a pack lacks a track, the packs after it in this list are tried in
 * order (Original, remastered, then Studio, then Synth). Change this one line to change it.
 */
export const FALLBACK_ORDER: readonly PackId[] = ["remaster", "studio", "synth"];

/** The packs to look in, in order, for a player who picked `selected`. */
export function packChain(selected: PackId): PackId[] {
  return FALLBACK_ORDER.slice(FALLBACK_ORDER.indexOf(selected));
}

/** The rulesets a town or career can run (Solo's "original" is Classic with its fixes off). */
export const RULESETS = ["classic", "expanded"] as const;
export type Ruleset = (typeof RULESETS)[number];

/** What is on screen: the front door, a town, a Solo career, the Daily Challenge, museum mode. */
export const PLAY_MODES = ["door", "town", "solo", "daily", "museum"] as const;
export type PlayMode = (typeof PLAY_MODES)[number];

export interface PlayContext {
  ruleset: Ruleset;
  mode: PlayMode;
}

/** The front door, and what the client starts in. */
export const DOOR_CONTEXT: PlayContext = { ruleset: "classic", mode: "door" };

/**
 * THE SELECTION TABLE: the pack "auto" plays, by mode, then ruleset (decision 15a). Classic towns,
 * Classic careers and museum mode: Original, remastered. Expanded towns, Expanded careers and the
 * Daily Challenge: Studio. The front door is the original game's, so it is the remaster's. The
 * Daily Challenge and museum mode each exist in one ruleset only; their other cell is never
 * reached, and says the same.
 */
export const AUTO_PACK: Record<PlayMode, Record<Ruleset, PackId>> = {
  door: { classic: "remaster", expanded: "remaster" },
  town: { classic: "remaster", expanded: "studio" },
  solo: { classic: "remaster", expanded: "studio" },
  daily: { classic: "studio", expanded: "studio" },
  museum: { classic: "remaster", expanded: "remaster" },
};

/** The pack that actually plays for a setting in a context. An explicit pack wins over "auto". */
export function effectivePack(setting: PackSetting, context: PlayContext): PackId {
  return setting === "auto" ? AUTO_PACK[context.mode][context.ruleset] : setting;
}

/** Why "auto" chose as it did, for the settings note. */
export type AutoReason =
  | "door"
  | "classic-town"
  | "classic-solo"
  | "expanded-town"
  | "expanded-solo"
  | "daily"
  | "museum";

export function autoReason(context: PlayContext): AutoReason {
  switch (context.mode) {
    case "door":
    case "daily":
    case "museum":
      return context.mode;
    default:
      return `${context.ruleset}-${context.mode}`;
  }
}

export interface ResolvedTrack {
  pack: PackId;
  track: ManifestTrack;
}

/**
 * Where a track plays from: the first pack in the selection's chain whose manifest has it.
 * A pack whose manifest is missing (null or undefined) is skipped; null when no pack has it.
 */
export function resolveTrack(
  manifests: Partial<Record<PackId, AudioManifest | null>>,
  id: string,
  selected: PackId,
): ResolvedTrack | null {
  for (const pack of packChain(selected)) {
    const track = manifests[pack]?.tracks[id];
    if (track) return { pack, track };
  }
  return null;
}

/**
 * Stem gains for a track's layer mode from the mood layers (`moodLayers`: calm always 1, uneasy
 * and angry ramping in). "mix" layers add up, so the gains pass through. "crossfade" stems are
 * whole pieces, one heard at a time: the same mood maps to weights that sum to one (calm fades
 * out as uneasy comes in, uneasy as angry comes in), as equal-power gains.
 */
export function stemGains(mode: ManifestTrack["layerMode"], layers: readonly number[]): number[] {
  if (mode !== "crossfade") return [...layers];
  const n = layers.length;
  const w = new Array<number>(n).fill(0);
  // walk down from the most intense layer: each takes its ramp of what is left
  let left = 1;
  for (let i = n - 1; i >= 1; i--) {
    const g = Math.max(0, Math.min(1, layers[i] ?? 0));
    w[i] = left * g;
    left -= w[i] as number;
  }
  w[0] = left;
  return w.map((x) => Math.sqrt(Math.max(0, x)));
}

/**
 * The next bar line, in context time, of a loop that started playing at `startedAt` from
 * `loopStart` (seconds into the file) and loops between `loopStart` and `loopEnd`. With no tempo
 * it returns `now` (switch at once).
 */
export function nextBarTime(
  now: number,
  startedAt: number,
  track: Pick<ManifestTrack, "bpm" | "beatsPerBar" | "loopStart" | "loopEnd">,
): number {
  const { bpm, beatsPerBar, loopStart, loopEnd } = track;
  if (!bpm || !beatsPerBar || loopStart === undefined || loopEnd === undefined) return now;
  const bar = (60 / bpm) * beatsPerBar;
  const period = loopEnd - loopStart;
  if (!(bar > 0) || !(period > 0)) return now;
  const pos = (((now - startedAt) % period) + period) % period;
  const next = Math.ceil(pos / bar - 1e-9) * bar;
  return now + (Math.min(next, period) - pos);
}
